import { useState } from "react";
import { Slider } from "@nativecn/ui/components/slider";

export default function App() {
  const [value, setValue] = useState(40);
  return (
    <Slider
      value={value}
      onValueChange={setValue}
      min={0}
      max={100}
      step={1}
    />
  );
}
